document:
query FeaturedProductsQuery($channel: String!) {
  ...FeaturedProducts
}

fragment FeaturedProducts on Query {
  collection(slug: "featured-products", channel: $channel) {
    id
    name
    backgroundImage {
      url
    }
    products(first: 20) {
      edges {
        node {
          ...FeaturedProduct
        }
      }
    }
  }
}

fragment FeaturedProduct on Product {
  ...BasicProductFields
  ...ProductPricingField
  category {
    id
    name
  }
}

fragment BasicProductFields on Product {
  id
  slug
  name
  thumbnail {
    url
    alt
  }
  thumbnail2x: thumbnail(size: 510) {
    url
  }
}

fragment ProductPricingField on Product {
  pricing {
    onSale
    priceRangeUndiscounted {
      start {
        ...TaxedPrice
      }
      stop {
        ...TaxedPrice
      }
    }
    priceRange {
      start {
        ...TaxedPrice
      }
      stop {
        ...TaxedPrice
      }
    }
  }
}

fragment TaxedPrice on TaxedMoney {
  gross {
    ...Price
  }
  net {
    ...Price
  }
}

fragment Price on Money {
  amount
  currency
}
